SPECIAL_NAMES <- c("FILENAME", "FNR", "FS", "NF", "NR", "OFS", "ORS", "SUBSEP")
new_table <- function() new.env(hash = TRUE, parent = emptyenv())
static_issue <- function(position, message) {
    stop(structure(list(message = message, position = position), class = c("static_issue", "error", "condition")))
}
transfer <- function(kind, value = UNINITIALIZED) {
    stop(structure(list(message = kind, kind = kind, value = value), class = c("awk_transfer", "error", "condition")))
}
new_analysis <- function(items) {
    analysis <- record(items = items, functions = Filter(function(item) item$kind == "function", items),
        rules = Filter(function(item) item$kind == "rule", items), function_table = new_table(),
        global_names = new_table(), bindings = new_table(), array_names = new_table(), statement_lines = new_table(),
        nodes = list(), errors = list())
    for (name in SPECIAL_NAMES) {
        analysis$global_names[[name]] <- TRUE
        analysis$bindings[[paste0("0:", name)]] <- list(scope = 0L, name = name, key = paste0("0:", name))
    }
    analysis
}
static_error <- function(analysis, position, priority, message) {
    analysis$errors[[length(analysis$errors) + 1L]] <- list(position = position, priority = priority, message = message)
}
resolve_name <- function(analysis, node, function_node) {
    local_name <- !is.null(function_node) && node$name %in% function_node$parameter_names
    scope <- if (local_name) function_node$function_id else 0L
    key <- paste0(scope, ":", node$name)
    node$binding <- list(scope = scope, name = node$name, key = key)
    analysis$bindings[[key]] <- node$binding
    if (!local_name) analysis$global_names[[node$name]] <- TRUE
    if (exists(node$name, analysis$function_table, inherits = FALSE)) {
        static_error(analysis, node$position, 3L, paste("function", node$name, "used as variable"))
    }
}
prepare <- function(analysis) {
    for (identifier in seq_along(analysis$functions)) {
        function_node <- analysis$functions[[identifier]]
        function_node$function_id <- identifier
        if (exists(function_node$name, analysis$function_table, inherits = FALSE)) {
            static_error(analysis, function_node$name_position, 1L, paste("function", function_node$name, "redefined"))
        } else analysis$function_table[[function_node$name]] <- function_node
        names <- character()
        for (parameter in function_node$parameters) {
            if (parameter$name %in% names) static_error(analysis, parameter$position, 2L, paste("duplicate parameter", parameter$name))
            names <- union(names, parameter$name)
        }
        function_node$parameter_names <- names
    }
    for (item in analysis$items) {
        function_node <- if (item$kind == "function") item else NULL
        pending <- list(item)
        while (length(pending)) {
            node <- pending[[length(pending)]]
            pending[[length(pending)]] <- NULL
            analysis$nodes[[length(analysis$nodes) + 1L]] <- node
            if (node$kind %in% STATEMENTS) analysis$statement_lines[[as.character(node$position[1L])]] <- TRUE
            if (node$kind %in% c("name", "array", "parameter")) {
                resolve_name(analysis, node, function_node)
            } else if (node$kind == "call") {
                target <- analysis$function_table[[node$name]]
                if (is.null(target)) static_error(analysis, node$position, 4L, paste("undefined function", node$name)) else {
                    node$target_function <- target
                    if (length(node$arguments) > length(target$parameters)) {
                        static_error(analysis, node$position, 5L, paste("too many arguments to", node$name))
                    }
                }
            }
            pending <- c(pending, rev(node$children))
        }
    }
    if (length(analysis$errors)) {
        order <- order(vapply(analysis$errors, function(error) error$position[1L], integer(1L)),
            vapply(analysis$errors, function(error) error$position[2L], integer(1L)),
            vapply(analysis$errors, function(error) error$priority, integer(1L)))
        error <- analysis$errors[[order[1L]]]
        static_issue(error$position, error$message)
    }
    links <- list()
    for (node in analysis$nodes) {
        if (node$kind == "array") analysis$array_names[[node$binding$key]] <- TRUE else if (node$kind %in% c("membership", "delete", "for_in")) {
            analysis$array_names[[node$array$binding$key]] <- TRUE
        } else if (node$kind == "builtin" && node$name == "split") {
            analysis$array_names[[node$arguments[[2L]]$binding$key]] <- TRUE
        } else if (node$kind == "call") {
            for (index in seq_len(min(length(node$arguments), length(node$target_function$parameters)))) {
                argument <- node$arguments[[index]]
                if (argument$kind == "name") links[[length(links) + 1L]] <- c(argument$binding$key, node$target_function$parameters[[index]]$binding$key)
            }
        }
    }
    repeat {
        previous <- length(analysis$array_names)
        for (link in links) {
            if (exists(link[1L], analysis$array_names, inherits = FALSE) || exists(link[2L], analysis$array_names, inherits = FALSE)) {
                analysis$array_names[[link[1L]]] <- TRUE
                analysis$array_names[[link[2L]]] <- TRUE
            }
        }
        if (length(analysis$array_names) == previous) break
    }
    analysis
}
arithmetic <- function(operator, first, second, position) {
    a <- to_number(first)
    b <- to_number(second)
    if (operator %in% c("/", "%")) {
        if (b == 0L) runtime_issue(position, "division by zero")
        quotient <- abs(a) %/% abs(b)
        if ((a < 0L) != (b < 0L)) quotient <- -quotient
        result <- if (operator == "/") quotient else a - quotient * b
    } else if (operator == "^") {
        if (b < 0L) runtime_issue(position, "negative exponent")
        result <- 1L
        base <- a
        while (b > 0L) {
            if (b %% 2L == 1L) result <- result * base
            b <- b %/% 2L
            if (b > 0L) base <- base * base
        }
    } else if (operator == "+") result <- a + b else if (operator == "-") result <- a - b else result <- a * b
    number(result)
}
new_engine <- function(analysis, options, operands) {
    globals <- new_table()
    global_names <- new_table()
    for (name in ls(analysis$global_names, all.names = TRUE)) {
        globals[[name]] <- if (exists(paste0("0:", name), analysis$array_names, inherits = FALSE)) new_array() else UNINITIALIZED
        global_names[[name]] <- TRUE
    }
    initial <- list(FILENAME = string_value(""), FNR = number(0L), FS = string_value(" "), NF = number(0L),
        NR = number(0L), OFS = string_value(" "), ORS = string_value("\n"), SUBSEP = string_value(intToUtf8(28L)))
    for (name in names(initial)) globals[[name]] <- initial[[name]]
    lines <- new_table()
    for (line in ls(analysis$statement_lines)) lines[[line]] <- 0L
    for (rule in analysis$rules) {
        rule$count <- 0L
        rule$inside <- FALSE
    }
    for (function_node in analysis$functions) {
        function_node$call_count <- function_node$active_calls <- function_node$max_depth <- 0L
    }
    record(analysis = analysis, options = options, operands = operands, globals = globals, global_names = global_names,
        local_frames = list(), record = new_record(function(name) globals[[name]]), streams = new_streams(), lines = lines,
        phase = "BEGIN", exit_status = 0L, error = NULL, operand_position = 1L, current_operand = NULL,
        input_lines = character(), input_position = 1L)
}
variable <- function(engine, binding) {
    if (binding$scope != 0L) return(engine$local_frames[[length(engine$local_frames)]][[binding$name]])
    if (binding$name == "NF") number(length(engine$record$fields)) else engine$globals[[binding$name]]
}
global_value <- function(engine, name) variable(engine, list(scope = 0L, name = name))
assign_global_input <- function(engine, name, text) {
    engine$global_names[[name]] <- TRUE
    engine$globals[[name]] <- input_value(text)
}
subscript <- function(engine, expressions) {
    values <- vapply(expressions, function(expression) to_string(evaluate(engine, expression)), character(1L))
    paste0(values, collapse = to_string(global_value(engine, "SUBSEP")))
}
location <- function(engine, node) {
    if (node$kind == "name") return(list(kind = "variable", binding = node$binding))
    if (node$kind == "array") {
        key <- subscript(engine, node$indexes)
        return(list(kind = "array", array = variable(engine, node$binding), key = key))
    }
    index <- to_number(evaluate(engine, node$index))
    if (index < 0L) runtime_issue(node$position, "negative field index")
    list(kind = "field", index = index)
}
read_location <- function(engine, place) {
    if (place$kind == "variable") return(variable(engine, place$binding))
    if (place$kind == "field") return(read_field(engine$record, place$index))
    map_get(place$array, place$key, create = TRUE)
}
store <- function(engine, place, value, position) {
    force(value)
    if (place$kind == "field") write_field(engine$record, place$index, value) else if (place$kind == "array") {
        map_set(place$array, place$key, value)
    } else if (place$binding$scope != 0L) {
        engine$local_frames[[length(engine$local_frames)]][[place$binding$name]] <- value
    } else if (place$binding$name == "NF") {
        size <- to_number(value)
        if (size < 0L) runtime_issue(position, "negative NF")
        resize_fields(engine$record, size)
    } else engine$globals[[place$binding$name]] <- value
}
evaluate <- function(engine, node) {
    kind <- node$kind
    if (kind == "number") return(number(node$value))
    if (kind == "string") return(string_value(node$value))
    if (kind %in% LVALUE_KINDS) return(read_location(engine, location(engine, node)))
    if (kind == "paren") return(evaluate(engine, node$expression))
    if (kind == "assignment") {
        place <- location(engine, node$location)
        value <- evaluate(engine, node$value)
        if (node$operator != "=") value <- arithmetic(substr(node$operator, 1L, nchar(node$operator) - 1L), read_location(engine, place), value, node$position)
        store(engine, place, value, node$position)
        return(read_location(engine, place))
    }
    if (kind == "increment") {
        place <- location(engine, node$location)
        old <- to_number(read_location(engine, place))
        value <- old + node$delta
        store(engine, place, number(value), node$position)
        return(number(if (node$prefix) value else old))
    }
    if (kind == "conditional") return(evaluate(engine, if (truth(evaluate(engine, node$condition))) node$first else node$second))
    if (kind == "unary") {
        value <- evaluate(engine, node$operand)
        if (node$operator == "!") return(number(!truth(value)))
        integer <- to_number(value)
        return(number(if (node$operator == "-") -integer else integer))
    }
    if (kind == "membership") {
        key <- subscript(engine, node$indexes)
        return(number(map_has(variable(engine, node$array$binding), key)))
    }
    if (kind == "binary") {
        first <- evaluate(engine, node$left)
        operator <- node$operator
        if (operator == "||" && truth(first)) return(number(1L))
        if (operator == "&&" && !truth(first)) return(number(0L))
        second <- evaluate(engine, node$right)
        if (operator %in% c("&&", "||")) return(number(truth(second)))
        if (operator == "concat") return(string_value(paste0(to_string(first), to_string(second))))
        if (operator %in% COMPARISONS) {
            order <- compare_values(first, second)
            result <- switch(operator, "<" = order < 0L, "<=" = order <= 0L, "==" = order == 0L,
                "!=" = order != 0L, ">=" = order >= 0L, ">" = order > 0L)
            return(number(result))
        }
        return(arithmetic(operator, first, second, node$position))
    }
    if (kind == "call") return(call_function(engine, node))
    if (kind == "builtin") return(evaluate_builtin(engine, node))
    evaluate_getline(engine, node)
}
call_function <- function(engine, node) {
    function_node <- node$target_function
    frame <- new_table()
    for (index in seq_along(function_node$parameters)) {
        parameter <- function_node$parameters[[index]]
        is_array <- exists(parameter$binding$key, engine$analysis$array_names, inherits = FALSE)
        if (index <= length(node$arguments)) {
            argument <- node$arguments[[index]]
            value <- if (is_array) variable(engine, argument$binding) else evaluate(engine, argument)
        } else value <- if (is_array) new_array() else UNINITIALIZED
        frame[[parameter$name]] <- value
    }
    function_node$call_count <- function_node$call_count + 1L
    function_node$active_calls <- function_node$active_calls + 1L
    function_node$max_depth <- max(function_node$max_depth, function_node$active_calls)
    engine$local_frames[[length(engine$local_frames) + 1L]] <- frame
    on.exit({
        engine$local_frames[[length(engine$local_frames)]] <- NULL
        function_node$active_calls <- function_node$active_calls - 1L
    })
    tryCatch({
        execute_statement(engine, function_node$body)
        UNINITIALIZED
    }, awk_transfer = function(transfer) {
        if (transfer$kind == "return") transfer$value else stop(transfer)
    })
}
evaluate_builtin <- function(engine, node) {
    name <- node$name
    arguments <- node$arguments
    if (name == "length") {
        if (!length(arguments)) return(number(nchar(to_string(engine$record$zero))))
        argument <- arguments[[1L]]
        if (argument$kind == "name" && exists(argument$binding$key, engine$analysis$array_names, inherits = FALSE)) {
            return(number(variable(engine, argument$binding)$size))
        }
        return(number(nchar(to_string(evaluate(engine, argument)))))
    }
    if (name == "split") {
        text <- to_string(evaluate(engine, arguments[[1L]]))
        separator <- if (length(arguments) == 3L) to_string(evaluate(engine, arguments[[3L]])) else to_string(global_value(engine, "FS"))
        array <- variable(engine, arguments[[2L]]$binding)
        map_clear(array)
        pieces <- split_pieces(text, separator)
        for (index in seq_along(pieces)) map_set(array, as.character(index), input_value(pieces[index]))
        return(number(length(pieces)))
    }
    if (name == "close") {
        filename <- to_string(evaluate(engine, arguments[[1L]]))
        return(number(close_streams(engine$streams, filename)))
    }
    values <- lapply(arguments, function(argument) evaluate(engine, argument))
    invoke_builtin(name, values, node$position)
}
evaluate_getline <- function(engine, node) {
    if (!is.null(node$filename)) {
        filename <- to_string(evaluate(engine, node$filename))
        found <- getline_input(engine$streams, filename)
        status <- found$status
        line <- found$line
    } else if (engine$phase == "END") return(number(0L)) else {
        line <- next_record(engine)
        status <- if (is.null(line)) 0L else 1L
    }
    if (status == 1L) {
        if (is.null(node$target)) set_record(engine$record, line) else {
            place <- location(engine, node$target)
            store(engine, place, input_value(line), node$position)
        }
    }
    number(status)
}
execute_output <- function(engine, node) {
    arguments <- lapply(node$arguments, function(argument) evaluate(engine, argument))
    if (node$kind == "print") {
        if (!length(arguments)) arguments <- list(engine$record$zero)
        values <- vapply(arguments, to_string, character(1L))
        text <- paste0(paste0(values, collapse = to_string(global_value(engine, "OFS"))), to_string(global_value(engine, "ORS")))
    } else text <- format_output(arguments, node$position)
    filename <- if (is.null(node$filename)) NULL else to_string(evaluate(engine, node$filename))
    write_output(engine$streams, text, filename, node$redirect, node$redirect_position)
}
execute_loop_body <- function(engine, body) {
    tryCatch({
        execute_statement(engine, body)
        TRUE
    }, awk_transfer = function(transfer) {
        if (transfer$kind == "break") FALSE else if (transfer$kind == "continue") TRUE else stop(transfer)
    })
}
execute_statement <- function(engine, node) {
    kind <- node$kind
    if (kind == "block") {
        for (child in node$statements) execute_statement(engine, child)
        return(invisible(NULL))
    }
    if (kind == "empty") return(invisible(NULL))
    line <- as.character(node$position[1L])
    engine$lines[[line]] <- engine$lines[[line]] + 1L
    if (kind == "expression_statement") evaluate(engine, node$expression) else if (kind %in% c("print", "printf")) {
        execute_output(engine, node)
    } else if (kind == "if") {
        branch <- if (truth(evaluate(engine, node$condition))) node$first else node$second
        if (!is.null(branch)) execute_statement(engine, branch)
    } else if (kind == "while") {
        while (truth(evaluate(engine, node$condition))) if (!execute_loop_body(engine, node$body)) break
    } else if (kind == "do") {
        repeat {
            if (!execute_loop_body(engine, node$body)) break
            if (!truth(evaluate(engine, node$condition))) break
        }
    } else if (kind == "for") {
        if (!is.null(node$initial)) evaluate(engine, node$initial)
        while (is.null(node$condition) || truth(evaluate(engine, node$condition))) {
            if (!execute_loop_body(engine, node$body)) break
            if (!is.null(node$update)) evaluate(engine, node$update)
        }
    } else if (kind == "for_in") {
        keys <- ordered_subscripts(map_keys(variable(engine, node$array$binding)))
        for (key in keys) {
            store(engine, list(kind = "variable", binding = node$variable$binding), input_value(key), node$variable$position)
            if (!execute_loop_body(engine, node$body)) break
        }
    } else if (kind == "delete") {
        array <- variable(engine, node$array$binding)
        if (is.null(node$indexes)) map_clear(array) else {
            key <- subscript(engine, node$indexes)
            map_remove(array, key)
        }
    } else if (kind == "next") {
        if (engine$phase %in% c("BEGIN", "END")) runtime_issue(node$position, "next used in BEGIN or END")
        transfer("next")
    } else if (kind == "exit") {
        if (!is.null(node$value)) engine$exit_status <- to_number(evaluate(engine, node$value))
        transfer("exit")
    } else if (kind == "return") {
        value <- if (is.null(node$value)) UNINITIALIZED else evaluate(engine, node$value)
        transfer("return", value)
    } else transfer(kind)
    invisible(NULL)
}
next_record <- function(engine) {
    repeat {
        if (engine$input_position <= length(engine$input_lines)) {
            line <- engine$input_lines[engine$input_position]
            engine$input_position <- engine$input_position + 1L
            engine$current_operand$records <- engine$current_operand$records + 1L
            engine$globals[["NR"]] <- number(to_number(global_value(engine, "NR")) + 1L)
            engine$globals[["FNR"]] <- number(to_number(global_value(engine, "FNR")) + 1L)
            return(line)
        }
        if (engine$operand_position > length(engine$operands)) return(NULL)
        operand <- engine$operands[[engine$operand_position]]
        engine$operand_position <- engine$operand_position + 1L
        if (operand$kind == "assignment") assign_global_input(engine, operand$name, operand$value) else {
            engine$current_operand <- operand
            engine$input_lines <- read_records(operand$name)
            engine$input_position <- 1L
            engine$globals[["FILENAME"]] <- string_value(operand$name)
            engine$globals[["FNR"]] <- number(0L)
        }
    }
}
run_actions <- function(engine, phase) {
    engine$phase <- phase
    for (rule in engine$analysis$rules) {
        if (rule$flavor == phase) {
            rule$count <- rule$count + 1L
            execute_statement(engine, rule$action)
        }
    }
}
rule_matches <- function(engine, rule) {
    if (rule$flavor == "all") return(TRUE)
    if (rule$flavor == "pattern") return(truth(evaluate(engine, rule$patterns[[1L]])))
    if (!rule$inside && truth(evaluate(engine, rule$patterns[[1L]]))) rule$inside <- TRUE
    if (!rule$inside) return(FALSE)
    if (truth(evaluate(engine, rule$patterns[[2L]]))) rule$inside <- FALSE
    TRUE
}
run_records <- function(engine) {
    if (!any(vapply(engine$analysis$rules, function(rule) rule$flavor != "BEGIN", logical(1L)))) return(invisible(NULL))
    engine$phase <- "records"
    rules <- Filter(function(rule) !rule$flavor %in% c("BEGIN", "END"), engine$analysis$rules)
    repeat {
        line <- next_record(engine)
        if (is.null(line)) return(invisible(NULL))
        set_record(engine$record, line)
        tryCatch({
            for (rule in rules) {
                if (rule_matches(engine, rule)) {
                    rule$count <- rule$count + 1L
                    if (is.null(rule$action)) {
                        write_output(engine$streams, paste0(to_string(engine$record$zero), to_string(global_value(engine, "ORS"))))
                    } else execute_statement(engine, rule$action)
                }
            }
        }, awk_transfer = function(transfer) {
            if (transfer$kind != "next") stop(transfer)
        })
    }
}
execute <- function(engine) {
    tryCatch({
        for (option in engine$options) assign_global_input(engine, option$name, option$value)
        tryCatch({
            run_actions(engine, "BEGIN")
            run_records(engine)
        }, awk_transfer = function(transfer) {
            if (transfer$kind != "exit") stop(transfer)
        })
        tryCatch(run_actions(engine, "END"), awk_transfer = function(transfer) {
            if (transfer$kind != "exit") stop(transfer)
        })
    }, runtime_issue = function(error) engine$error <- error)
}
statistics <- function(engine) {
    status <- if (is.null(engine$error)) paste("status: exit", engine$exit_status) else {
        paste0("status: runtime error at ", engine$error$position[1L], ":", engine$error$position[2L], ": ", engine$error$message)
    }
    lines <- c(status, "[inputs]")
    for (operand in engine$operands) if (operand$kind == "file") lines <- c(lines, paste0(operand$name, " records=", operand$records))
    lines <- c(lines, "[getline]")
    for (name in engine$streams$input_order) {
        source <- map_get(engine$streams$inputs, name)
        lines <- c(lines, paste(name, if (source$ever_opened) paste0("reads=", source$reads) else "missing"))
    }
    lines <- c(lines, "[rules]")
    for (rule in engine$analysis$rules) lines <- c(lines, paste0(rule$position[1L], ":", rule$position[2L], " ", rule$flavor, " count=", rule$count))
    lines <- c(lines, "[functions]")
    for (function_node in engine$analysis$functions) lines <- c(lines, paste0(function_node$name, " calls=", function_node$call_count, " depth=", function_node$max_depth))
    lines <- c(lines, "[outputs]", paste0("stdout.txt writes=", engine$streams$stdout$writes, " bytes=", engine$streams$stdout$bytes))
    for (name in engine$streams$output_order) {
        output <- map_get(engine$streams$outputs, name)
        lines <- c(lines, paste0(name, " writes=", output$writes, " bytes=", output$bytes))
    }
    lines <- c(lines, "[lines]")
    for (line in sort(as.integer(ls(engine$lines)))) lines <- c(lines, paste0(line, " count=", engine$lines[[as.character(line)]]))
    lines <- c(lines, "[globals]")
    for (name in sort(ls(engine$global_names, all.names = TRUE), method = "radix")) {
        value <- global_value(engine, name)
        text <- if (exists(paste0("0:", name), engine$analysis$array_names, inherits = FALSE)) paste0("array (", value$size, ")") else describe_value(value)
        lines <- c(lines, paste(name, "=", text))
    }
    lines
}
main <- function() {
    options(expressions = 100000L)
    arguments <- parse_arguments(readLines("input/args.txt", warn = FALSE))
    source_lines <- readLines("input/program.awk", warn = FALSE)
    source <- if (length(source_lines)) paste0(paste0(source_lines, collapse = "\n"), "\n") else ""
    result <- tryCatch({
        items <- parse_program(new_parser(tokenize(source)))
        analysis <- prepare(new_analysis(items))
        engine <- new_engine(analysis, arguments$options, arguments$operands)
        execute(engine)
        list(lines = statistics(engine), streams = engine$streams)
    }, syntax_issue = function(error) {
        list(lines = paste0("status: syntax error at ", error$position[1L], ":", error$position[2L]), streams = new_streams())
    }, static_issue = function(error) {
        list(lines = paste0("status: error at ", error$position[1L], ":", error$position[2L], ": ", error$message), streams = new_streams())
    })
    save_streams(result$streams)
    writeLines(result$lines, "output/stats.txt", useBytes = TRUE)
}
main()

record <- function(...) list2env(list(...), parent = emptyenv())
ASSIGNMENTS <- c("=", "+=", "-=", "*=", "/=", "%=", "^=")
COMPARISONS <- c("<", "<=", "==", "!=", ">=", ">")
LVALUE_KINDS <- c("name", "array", "field")
STATEMENTS <- c("if", "while", "do", "for", "for_in", "print", "printf", "delete", "next", "break", "continue", "exit", "return", "expression_statement")
awk_node <- function(kind, position, children = list(), ...) {
    list2env(c(list(kind = kind, position = position, children = Filter(Negate(is.null), children)), list(...)), parent = emptyenv())
}
new_parser <- function(tokens) record(tokens = tokens, index = 1L, in_function = FALSE, phase = NULL, loop_depth = 0L)
current_token <- function(parser) parser$tokens[[parser$index]]
take_token <- function(parser) {
    token <- current_token(parser)
    parser$index <- parser$index + 1L
    token
}
syntax_error <- function(parser, position = current_token(parser)$position) syntax_issue(position)
accept_token <- function(parser, spelling) {
    if (current_token(parser)$spelling == spelling) take_token(parser) else NULL
}
expect_token <- function(parser, spelling) {
    if (current_token(parser)$spelling != spelling) syntax_error(parser)
    take_token(parser)
}
parse_name <- function(parser) {
    if (current_token(parser)$kind != "name") syntax_error(parser)
    token <- take_token(parser)
    awk_node("name", token$position, name = token$spelling)
}
skip_newlines <- function(parser) while (!is.null(accept_token(parser, "\n"))) {}
parse_program <- function(parser) {
    items <- list()
    while (current_token(parser)$kind != "end") {
        if (current_token(parser)$spelling %in% c("\n", ";")) {
            take_token(parser)
            next
        }
        opening <- current_token(parser)
        if (!is.null(accept_token(parser, "function"))) {
            if (!current_token(parser)$kind %in% c("name", "function_name")) syntax_error(parser)
            name <- take_token(parser)
            expect_token(parser, "(")
            parameters <- list()
            if (current_token(parser)$spelling != ")") {
                repeat {
                    parameter <- parse_name(parser)
                    parameter$kind <- "parameter"
                    parameters[[length(parameters) + 1L]] <- parameter
                    if (is.null(accept_token(parser, ","))) break
                    skip_newlines(parser)
                }
            }
            expect_token(parser, ")")
            skip_newlines(parser)
            parser$in_function <- TRUE
            body <- parse_block(parser)
            parser$in_function <- FALSE
            items[[length(items) + 1L]] <- awk_node("function", opening$position, c(parameters, list(body)),
                name = name$spelling, name_position = name$position, parameters = parameters, body = body)
            next
        }
        patterns <- list()
        if (opening$spelling %in% c("BEGIN", "END")) flavor <- take_token(parser)$spelling else if (opening$spelling == "{") flavor <- "all" else {
            patterns[[1L]] <- parse_expression(parser)
            if (!is.null(accept_token(parser, ","))) {
                skip_newlines(parser)
                patterns[[2L]] <- parse_expression(parser)
            }
            flavor <- if (length(patterns) == 2L) "range" else "pattern"
        }
        parser$phase <- flavor
        if (flavor %in% c("BEGIN", "END", "all") || current_token(parser)$spelling == "{") {
            action <- parse_block(parser)
        } else {
            if (!current_token(parser)$spelling %in% c("\n", ";") && current_token(parser)$kind != "end") syntax_error(parser)
            action <- NULL
        }
        parser$phase <- NULL
        items[[length(items) + 1L]] <- awk_node("rule", opening$position, c(patterns, list(action)), flavor = flavor, patterns = patterns, action = action)
    }
    items
}
parse_block <- function(parser) {
    opening <- expect_token(parser, "{")
    statements <- list()
    while (current_token(parser)$spelling != "}") {
        if (current_token(parser)$spelling %in% c("\n", ";")) take_token(parser) else statements[[length(statements) + 1L]] <- parse_statement(parser)
    }
    expect_token(parser, "}")
    awk_node("block", opening$position, statements, statements = statements)
}
parse_condition <- function(parser) {
    expect_token(parser, "(")
    value <- parse_expression(parser)
    expect_token(parser, ")")
    value
}
parse_loop_body <- function(parser) {
    skip_newlines(parser)
    parser$loop_depth <- parser$loop_depth + 1L
    body <- parse_statement(parser)
    parser$loop_depth <- parser$loop_depth - 1L
    body
}
parse_terminator <- function(parser) {
    if (current_token(parser)$spelling %in% c(";", "\n")) take_token(parser) else if (current_token(parser)$spelling != "}") syntax_error(parser)
}
parse_statement <- function(parser) {
    token <- current_token(parser)
    spelling <- token$spelling
    if (spelling == "{") return(parse_block(parser))
    if (!is.null(accept_token(parser, ";"))) return(awk_node("empty", token$position))
    if (!is.null(accept_token(parser, "if"))) {
        condition <- parse_condition(parser)
        skip_newlines(parser)
        first <- parse_statement(parser)
        skip_newlines(parser)
        second <- NULL
        if (!is.null(accept_token(parser, "else"))) {
            skip_newlines(parser)
            second <- parse_statement(parser)
        }
        return(awk_node("if", token$position, list(condition, first, second), condition = condition, first = first, second = second))
    }
    if (!is.null(accept_token(parser, "while"))) {
        condition <- parse_condition(parser)
        body <- parse_loop_body(parser)
        return(awk_node("while", token$position, list(condition, body), condition = condition, body = body))
    }
    if (!is.null(accept_token(parser, "do"))) {
        body <- parse_loop_body(parser)
        skip_newlines(parser)
        expect_token(parser, "while")
        condition <- parse_condition(parser)
        parse_terminator(parser)
        return(awk_node("do", token$position, list(body, condition), body = body, condition = condition))
    }
    if (!is.null(accept_token(parser, "for"))) {
        expect_token(parser, "(")
        index <- parser$index
        if (index + 3L <= length(parser$tokens) && parser$tokens[[index]]$kind == "name" &&
            parser$tokens[[index + 1L]]$spelling == "in" && parser$tokens[[index + 2L]]$kind == "name" && parser$tokens[[index + 3L]]$spelling == ")") {
            variable <- parse_name(parser)
            expect_token(parser, "in")
            array <- parse_name(parser)
            expect_token(parser, ")")
            body <- parse_loop_body(parser)
            return(awk_node("for_in", token$position, list(variable, array, body), variable = variable, array = array, body = body))
        }
        initial <- if (current_token(parser)$spelling == ";") NULL else parse_expression(parser)
        expect_token(parser, ";")
        skip_newlines(parser)
        condition <- if (current_token(parser)$spelling == ";") NULL else parse_expression(parser)
        expect_token(parser, ";")
        skip_newlines(parser)
        update <- if (current_token(parser)$spelling == ")") NULL else parse_expression(parser)
        expect_token(parser, ")")
        body <- parse_loop_body(parser)
        return(awk_node("for", token$position, list(initial, condition, update, body), initial = initial, condition = condition, update = update, body = body))
    }
    if (spelling %in% c("print", "printf")) {
        take_token(parser)
        result <- parse_output(parser, token)
    } else if (spelling == "delete") {
        take_token(parser)
        array <- parse_name(parser)
        indexes <- NULL
        if (!is.null(accept_token(parser, "["))) {
            indexes <- parse_expression_list(parser)
            expect_token(parser, "]")
        }
        result <- awk_node("delete", token$position, c(list(array), indexes), array = array, indexes = indexes)
    } else if (spelling %in% c("next", "break", "continue", "exit", "return")) {
        take_token(parser)
        if (spelling == "next" && !parser$in_function && parser$phase %in% c("BEGIN", "END")) syntax_error(parser, token$position)
        if (spelling == "return" && !parser$in_function) syntax_error(parser, token$position)
        if (spelling %in% c("break", "continue") && parser$loop_depth == 0L) syntax_error(parser, token$position)
        value <- if (spelling %in% c("exit", "return") && !current_token(parser)$spelling %in% c(";", "\n", "}")) parse_expression(parser) else NULL
        result <- awk_node(spelling, token$position, list(value), value = value)
    } else {
        expression <- parse_expression(parser)
        result <- awk_node("expression_statement", token$position, list(expression), expression = expression)
    }
    parse_terminator(parser)
    result
}
parenthesized_output <- function(parser) {
    if (current_token(parser)$spelling != "(") return(FALSE)
    depth <- 0L
    for (index in seq.int(parser$index, length(parser$tokens) - 1L)) {
        spelling <- parser$tokens[[index]]$spelling
        if (spelling == "(") depth <- depth + 1L else if (spelling == ")") {
            depth <- depth - 1L
            if (depth == 0L) {
                following <- parser$tokens[[index + 1L]]
                return(following$spelling %in% c(";", "\n", "}", ">", ">>") || following$kind == "end")
            }
        }
    }
    FALSE
}
parse_output <- function(parser, token) {
    arguments <- list()
    if (parenthesized_output(parser)) {
        expect_token(parser, "(")
        arguments <- parse_expression_list(parser)
        expect_token(parser, ")")
    } else if (!current_token(parser)$spelling %in% c(";", "\n", "}", ">", ">>")) arguments <- parse_expression_list(parser, FALSE)
    if (token$spelling == "printf" && !length(arguments)) syntax_error(parser)
    redirect <- if (current_token(parser)$spelling %in% c(">", ">>")) take_token(parser) else NULL
    filename <- if (is.null(redirect)) NULL else parse_concatenation(parser)
    awk_node(token$spelling, token$position, c(arguments, list(filename)), arguments = arguments,
        redirect = if (is.null(redirect)) NULL else redirect$spelling,
        redirect_position = if (is.null(redirect)) NULL else redirect$position, filename = filename)
}
parse_expression_list <- function(parser, greater = TRUE) {
    result <- list(parse_expression(parser, greater))
    while (!is.null(accept_token(parser, ","))) {
        skip_newlines(parser)
        result[[length(result) + 1L]] <- parse_expression(parser, greater)
    }
    result
}
parse_expression <- function(parser, greater = TRUE) {
    left <- parse_conditional(parser, greater)
    if (left$kind %in% LVALUE_KINDS && current_token(parser)$spelling %in% ASSIGNMENTS) {
        operator <- take_token(parser)
        right <- parse_expression(parser, greater)
        return(awk_node("assignment", operator$position, list(left, right), operator = operator$spelling, location = left, value = right))
    }
    left
}
parse_conditional <- function(parser, greater) {
    condition <- parse_logical(parser, 0L, greater)
    operator <- accept_token(parser, "?")
    if (is.null(operator)) return(condition)
    first <- parse_conditional(parser, greater)
    expect_token(parser, ":")
    second <- parse_conditional(parser, greater)
    awk_node("conditional", operator$position, list(condition, first, second), condition = condition, first = first, second = second)
}
binary_node <- function(operator, left, right) {
    awk_node("binary", operator$position, list(left, right), operator = operator$spelling, left = left, right = right)
}
parse_logical <- function(parser, level, greater) {
    if (level == 2L) return(parse_membership(parser, greater))
    spelling <- if (level == 0L) "||" else "&&"
    left <- parse_logical(parser, level + 1L, greater)
    while (current_token(parser)$spelling == spelling) {
        operator <- take_token(parser)
        skip_newlines(parser)
        left <- binary_node(operator, left, parse_logical(parser, level + 1L, greater))
    }
    left
}
parse_membership <- function(parser, greater) {
    left <- parse_comparison(parser, greater)
    while (current_token(parser)$spelling == "in") {
        operator <- take_token(parser)
        array <- parse_name(parser)
        left <- awk_node("membership", operator$position, list(left, array), indexes = list(left), array = array)
    }
    left
}
parse_comparison <- function(parser, greater) {
    left <- parse_concatenation(parser)
    while (current_token(parser)$spelling %in% COMPARISONS && (greater || current_token(parser)$spelling != ">")) {
        operator <- take_token(parser)
        left <- binary_node(operator, left, parse_concatenation(parser))
    }
    left
}
parse_concatenation <- function(parser) {
    left <- parse_additive(parser)
    while (current_token(parser)$kind %in% c("number", "string", "name", "function_name", "builtin") || current_token(parser)$spelling %in% c("$", "(", "++", "--")) {
        position <- current_token(parser)$position
        right <- parse_additive(parser)
        left <- awk_node("binary", position, list(left, right), operator = "concat", left = left, right = right)
    }
    left
}
parse_additive <- function(parser) {
    left <- parse_multiplicative(parser)
    while (current_token(parser)$spelling %in% c("+", "-")) {
        operator <- take_token(parser)
        left <- binary_node(operator, left, parse_multiplicative(parser))
    }
    left
}
parse_multiplicative <- function(parser) {
    left <- parse_unary(parser)
    while (current_token(parser)$spelling %in% c("*", "/", "%")) {
        operator <- take_token(parser)
        left <- binary_node(operator, left, parse_unary(parser))
    }
    left
}
parse_unary <- function(parser) {
    if (current_token(parser)$spelling %in% c("!", "-", "+")) {
        operator <- take_token(parser)
        operand <- parse_unary(parser)
        return(awk_node("unary", operator$position, list(operand), operator = operator$spelling, operand = operand))
    }
    left <- parse_postfix(parser)
    if (current_token(parser)$spelling == "^") {
        operator <- take_token(parser)
        left <- binary_node(operator, left, parse_unary(parser))
    }
    left
}
parse_prefix <- function(parser) {
    operator <- take_token(parser)
    location <- parse_lvalue(parser)
    awk_node("increment", operator$position, list(location), location = location,
        delta = if (operator$spelling == "++") 1L else -1L, prefix = TRUE)
}
parse_postfix <- function(parser) {
    if (current_token(parser)$spelling %in% c("++", "--")) return(parse_prefix(parser))
    left <- parse_atom(parser)
    if (left$kind %in% LVALUE_KINDS && current_token(parser)$spelling %in% c("++", "--")) {
        operator <- take_token(parser)
        return(awk_node("increment", operator$position, list(left), location = left,
            delta = if (operator$spelling == "++") 1L else -1L, prefix = FALSE))
    }
    left
}
parse_lvalue <- function(parser) {
    if (current_token(parser)$kind == "name") {
        node <- parse_name(parser)
        if (!is.null(accept_token(parser, "["))) {
            indexes <- parse_expression_list(parser)
            expect_token(parser, "]")
            return(awk_node("array", node$position, indexes, name = node$name, indexes = indexes))
        }
        return(node)
    }
    dollar <- accept_token(parser, "$")
    if (!is.null(dollar)) {
        index <- if (current_token(parser)$spelling %in% c("++", "--")) parse_prefix(parser) else parse_atom(parser)
        return(awk_node("field", dollar$position, list(index), index = index))
    }
    syntax_error(parser)
}
parse_atom <- function(parser) {
    token <- current_token(parser)
    if (token$kind %in% c("number", "string")) {
        take_token(parser)
        return(awk_node(token$kind, token$position, value = token$value))
    }
    if (token$kind == "name" || token$spelling == "$") return(parse_lvalue(parser))
    if (!is.null(accept_token(parser, "("))) {
        expressions <- parse_expression_list(parser)
        expect_token(parser, ")")
        if (length(expressions) == 1L) return(awk_node("paren", token$position, expressions, expression = expressions[[1L]]))
        expect_token(parser, "in")
        array <- parse_name(parser)
        return(awk_node("membership", token$position, c(expressions, list(array)), indexes = expressions, array = array))
    }
    if (token$kind %in% c("function_name", "builtin")) {
        take_token(parser)
        arguments <- list()
        if (!is.null(accept_token(parser, "("))) {
            if (current_token(parser)$spelling != ")") arguments <- parse_expression_list(parser)
            expect_token(parser, ")")
        } else if (token$kind == "function_name" || token$spelling != "length") syntax_error(parser)
        kind <- if (token$kind == "function_name") "call" else "builtin"
        if (kind == "builtin") check_builtin(parser, token, arguments)
        return(awk_node(kind, token$position, arguments, name = token$spelling, arguments = arguments))
    }
    if (!is.null(accept_token(parser, "getline"))) {
        target <- if (current_token(parser)$kind == "name" || current_token(parser)$spelling == "$") parse_lvalue(parser) else NULL
        filename <- if (!is.null(accept_token(parser, "<"))) parse_atom(parser) else NULL
        return(awk_node("getline", token$position, list(target, filename), target = target, filename = filename))
    }
    syntax_error(parser)
}
check_builtin <- function(parser, token, arguments) {
    count <- length(arguments)
    name <- token$spelling
    valid <- if (name == "length") {
        count %in% c(0L, 1L)
    } else if (name %in% c("substr", "split")) {
        count %in% c(2L, 3L)
    } else if (name == "index") {
        count == 2L
    } else if (name == "sprintf") {
        count >= 1L
    } else count == 1L
    if (!valid || (name == "split" && arguments[[2L]]$kind != "name")) syntax_error(parser, token$position)
}

valid_name <- function(name) {
    characters <- strsplit(name, "", fixed = TRUE)[[1L]]
    length(characters) > 0L && (letter(characters[1L]) || characters[1L] == "_") && all(vapply(characters, name_character, logical(1L)))
}
valid_filename <- function(name) {
    characters <- strsplit(name, "", fixed = TRUE)[[1L]]
    length(characters) > 0L && characters[1L] != "." && all(vapply(characters, function(character) {
        letter(character) || digit(character) || character %in% c(".", "_", "-")
    }, logical(1L)))
}
parse_arguments <- function(lines) {
    options <- operands <- list()
    for (line in lines) {
        if (startsWith(line, "-F ")) {
            options[[length(options) + 1L]] <- list(name = "FS", value = substring(line, 4L))
        } else if (startsWith(line, "-v ")) {
            assignment <- substring(line, 4L)
            equals <- literal_index(assignment, "=")
            options[[length(options) + 1L]] <- list(name = substr(assignment, 1L, equals - 1L), value = substring(assignment, equals + 1L))
        } else {
            equals <- literal_index(line, "=")
            name <- if (equals > 0L) substr(line, 1L, equals - 1L) else ""
            operand <- if (equals > 0L && valid_name(name)) {
                record(kind = "assignment", name = name, value = substring(line, equals + 1L), records = 0L)
            } else record(kind = "file", name = line, value = "", records = 0L)
            operands[[length(operands) + 1L]] <- operand
        }
    }
    list(options = options, operands = operands)
}
read_records <- function(name) readLines(file.path("input", name), warn = FALSE)
new_output <- function() record(head = NULL, tail = NULL, opened = FALSE, writes = 0L, bytes = 0L, chunks = 0L)
append_output <- function(output, text) {
    force(text)
    chunk <- record(text = text, next_chunk = NULL)
    if (is.null(output$head)) output$head <- chunk else output$tail$next_chunk <- chunk
    output$tail <- chunk
    output$writes <- output$writes + 1L
    output$bytes <- output$bytes + nchar(text)
    output$chunks <- output$chunks + 1L
}
content <- function(output) {
    parts <- character(output$chunks)
    chunk <- output$head
    index <- 1L
    while (!is.null(chunk)) {
        parts[index] <- chunk$text
        chunk <- chunk$next_chunk
        index <- index + 1L
    }
    paste0(parts, collapse = "")
}
new_streams <- function() record(stdout = new_output(), outputs = new_map(), output_order = character(), inputs = new_map(), input_order = character())
write_output <- function(streams, text, name = NULL, mode = NULL, position = NULL) {
    force(text)
    if (is.null(name)) {
        append_output(streams$stdout, text)
        return(invisible(NULL))
    }
    if (!valid_filename(name) || name %in% c("stdout.txt", "stats.txt")) runtime_issue(position, "invalid output file name")
    if (!map_has(streams$outputs, name)) {
        map_set(streams$outputs, name, new_output())
        streams$output_order <- c(streams$output_order, name)
    }
    output <- map_get(streams$outputs, name)
    if (!output$opened) {
        output$opened <- TRUE
        if (mode == ">") {
            output$head <- output$tail <- NULL
            output$bytes <- output$chunks <- 0L
        }
    }
    append_output(output, text)
}
getline_input <- function(streams, name) {
    if (!map_has(streams$inputs, name)) {
        map_set(streams$inputs, name, record(opened = FALSE, ever_opened = FALSE, lines = character(), position = 1L, reads = 0L))
        streams$input_order <- c(streams$input_order, name)
    }
    source <- map_get(streams$inputs, name)
    if (!source$opened) {
        path <- file.path("input", name)
        if (!valid_filename(name) || !file.exists(path) || dir.exists(path)) return(list(status = -1L, line = NULL))
        source$lines <- read_records(name)
        source$position <- 1L
        source$opened <- source$ever_opened <- TRUE
    }
    if (source$position > length(source$lines)) return(list(status = 0L, line = NULL))
    line <- source$lines[source$position]
    source$position <- source$position + 1L
    source$reads <- source$reads + 1L
    list(status = 1L, line = line)
}
close_streams <- function(streams, name) {
    closed <- FALSE
    for (table in list(streams$outputs, streams$inputs)) {
        if (map_has(table, name)) {
            stream <- map_get(table, name)
            if (stream$opened) {
                stream$opened <- FALSE
                closed <- TRUE
            }
        }
    }
    if (closed) 0L else -1L
}
save_streams <- function(streams) {
    writeChar(content(streams$stdout), "output/stdout.txt", eos = NULL, useBytes = TRUE)
    for (name in streams$output_order) writeChar(content(map_get(streams$outputs, name)), file.path("output", name), eos = NULL, useBytes = TRUE)
}

UNINITIALIZED <- list(kind = "uninitialized", text = "", numeric = 0L)
WHITESPACE <- c(" ", "\t", "\n")
number <- function(value) list(kind = "number", text = "", numeric = as.integer(value))
string_value <- function(text) list(kind = "string", text = text, numeric = 0L)
numeric_prefix <- function(text) {
    characters <- strsplit(text, "", fixed = TRUE)[[1L]]
    index <- 1L
    sign <- 1L
    value <- 0L
    while (index <= length(characters) && characters[index] %in% WHITESPACE) index <- index + 1L
    if (index <= length(characters) && characters[index] %in% c("+", "-")) {
        sign <- if (characters[index] == "-") -1L else 1L
        index <- index + 1L
    }
    while (index <= length(characters) && digit(characters[index])) {
        value <- value * 10L + utf8ToInt(characters[index]) - 48L
        index <- index + 1L
    }
    sign * value
}
input_value <- function(text) {
    characters <- strsplit(text, "", fixed = TRUE)[[1L]]
    beginning <- 1L
    finish <- length(characters)
    while (beginning <= finish && characters[beginning] %in% WHITESPACE) beginning <- beginning + 1L
    while (beginning <= finish && characters[finish] %in% WHITESPACE) finish <- finish - 1L
    if (beginning <= finish && characters[beginning] %in% c("+", "-")) beginning <- beginning + 1L
    numeric <- beginning <= finish && all(vapply(characters[seq.int(beginning, finish)], digit, logical(1L)))
    if (numeric) list(kind = "strnum", text = text, numeric = numeric_prefix(text)) else string_value(text)
}
to_number <- function(value) if (value$kind == "string") numeric_prefix(value$text) else value$numeric
to_string <- function(value) if (value$kind == "number") as.character(value$numeric) else if (value$kind == "uninitialized") "" else value$text
truth <- function(value) if (value$kind == "string") value$text != "" else value$numeric != 0L
ascii_compare <- function(a, b) {
    first <- utf8ToInt(a)
    second <- utf8ToInt(b)
    for (index in seq_len(min(length(first), length(second)))) {
        if (first[index] != second[index]) return(if (first[index] < second[index]) -1L else 1L)
    }
    as.integer(length(first) > length(second)) - as.integer(length(first) < length(second))
}
compare_values <- function(first, second) {
    if (first$kind != "string" && second$kind != "string") {
        a <- to_number(first)
        b <- to_number(second)
        return(as.integer(a > b) - as.integer(a < b))
    }
    ascii_compare(to_string(first), to_string(second))
}
new_map <- function() record(buckets = new.env(hash = TRUE, parent = emptyenv()), size = 0L)
new_array <- function() {
    array <- new_map()
    class(array) <- c("awk_array", "environment")
    array
}
map_hash <- function(key) {
    hash <- 0L
    for (code in utf8ToInt(key)) hash <- (hash * 31L + code) %% 1000003L
    paste0("k", hash)
}
map_entry <- function(map, key) {
    bucket <- map$buckets[[map_hash(key)]]
    for (entry in bucket) if (identical(entry$key, key)) return(entry)
    NULL
}
map_has <- function(map, key) !is.null(map_entry(map, key))
map_get <- function(map, key, default = UNINITIALIZED, create = FALSE) {
    entry <- map_entry(map, key)
    if (!is.null(entry)) return(entry$value)
    if (create) map_set(map, key, default)
    default
}
map_set <- function(map, key, value) {
    force(value)
    entry <- map_entry(map, key)
    if (is.null(entry)) {
        hash <- map_hash(key)
        bucket <- map$buckets[[hash]]
        bucket[[length(bucket) + 1L]] <- record(key = key, value = value)
        map$buckets[[hash]] <- bucket
        map$size <- map$size + 1L
    } else entry$value <- value
    invisible(value)
}
map_remove <- function(map, key) {
    hash <- map_hash(key)
    bucket <- map$buckets[[hash]]
    for (index in seq_along(bucket)) {
        if (identical(bucket[[index]]$key, key)) {
            bucket[[index]] <- NULL
            if (length(bucket)) map$buckets[[hash]] <- bucket else rm(list = hash, envir = map$buckets)
            map$size <- map$size - 1L
            return(invisible(NULL))
        }
    }
}
map_clear <- function(map) {
    map$buckets <- new.env(hash = TRUE, parent = emptyenv())
    map$size <- 0L
}
map_keys <- function(map) {
    result <- character(map$size)
    index <- 1L
    for (hash in ls(map$buckets, all.names = TRUE)) {
        for (entry in map$buckets[[hash]]) {
            result[index] <- entry$key
            index <- index + 1L
        }
    }
    result
}
ordered_subscripts <- function(keys) {
    integer_form <- vapply(keys, function(key) {
        if (key == "0") return(TRUE)
        digits <- if (startsWith(key, "-")) substring(key, 2L) else key
        characters <- strsplit(digits, "", fixed = TRUE)[[1L]]
        length(characters) > 0L && characters[1L] %in% as.character(1L:9L) && all(vapply(characters, digit, logical(1L)))
    }, logical(1L))
    integers <- keys[integer_form]
    c(integers[order(as.integer(integers))], sort(keys[!integer_form], method = "radix"))
}
literal_index <- function(text, sought, start = 1L) {
    if (sought == "" || nchar(sought) > nchar(text) - start + 1L) return(0L)
    for (index in seq.int(start, nchar(text) - nchar(sought) + 1L)) {
        if (substr(text, index, index + nchar(sought) - 1L) == sought) return(index)
    }
    0L
}
split_pieces <- function(text, separator) {
    if (text == "") return(character())
    if (separator == "") return(strsplit(text, "", fixed = TRUE)[[1L]])
    pieces <- character()
    if (separator != " ") {
        beginning <- 1L
        repeat {
            found <- literal_index(text, separator, beginning)
            if (found == 0L) break
            pieces <- c(pieces, if (found == beginning) "" else substr(text, beginning, found - 1L))
            beginning <- found + nchar(separator)
        }
        return(c(pieces, if (beginning > nchar(text)) "" else substring(text, beginning)))
    }
    characters <- strsplit(text, "", fixed = TRUE)[[1L]]
    beginning <- 0L
    for (index in seq_along(characters)) {
        if (characters[index] %in% WHITESPACE) {
            if (beginning != 0L) {
                pieces <- c(pieces, substr(text, beginning, index - 1L))
                beginning <- 0L
            }
        } else if (beginning == 0L) beginning <- index
    }
    if (beginning != 0L) pieces <- c(pieces, substring(text, beginning))
    pieces
}
new_record <- function(special) record(special = special, zero = string_value(""), fields = list())
set_record <- function(record, text) {
    force(text)
    record$zero <- input_value(text)
    record$fields <- lapply(split_pieces(text, to_string(record$special("FS"))), input_value)
}
read_field <- function(record, index) {
    if (index == 0L) record$zero else if (index <= length(record$fields)) record$fields[[index]] else UNINITIALIZED
}
rebuild_record <- function(record) {
    fields <- vapply(record$fields, to_string, character(1L))
    record$zero <- input_value(paste0(fields, collapse = to_string(record$special("OFS"))))
}
write_field <- function(record, index, value) {
    force(value)
    if (index == 0L) {
        set_record(record, to_string(value))
        return(invisible(NULL))
    }
    while (length(record$fields) < index) record$fields[[length(record$fields) + 1L]] <- string_value("")
    record$fields[[index]] <- value
    rebuild_record(record)
}
resize_fields <- function(record, size) {
    if (size < length(record$fields)) record$fields <- head(record$fields, size)
    while (length(record$fields) < size) record$fields[[length(record$fields) + 1L]] <- string_value("")
    rebuild_record(record)
}
quoted_value <- function(text) {
    pieces <- vapply(strsplit(text, "", fixed = TRUE)[[1L]], function(character) {
        if (character == "\"") "\\\"" else if (character == "\\") "\\\\" else if (character == "\n") "\\n" else if (character == "\t") "\\t" else {
            code <- utf8ToInt(character)
            if (code >= 32L && code <= 126L) character else paste0("\\", sprintf("%03o", code))
        }
    }, character(1L))
    paste0("\"", paste0(pieces, collapse = ""), "\"")
}
describe_value <- function(value) {
    if (value$kind == "number") return(as.character(value$numeric))
    if (value$kind == "uninitialized") return("(uninitialized)")
    paste0(quoted_value(value$text), if (value$kind == "strnum") " (strnum)" else "")
}
